const labels={overview:'Panoramica',programs:'I miei percorsi',universities:'Le mie università',favorites:'La mia selezione',compare:'Confronta',applications:'Candidature'};
const stages=['Da valutare','In preparazione','Inviata','Esito ricevuto'];
const commandPages=[['overview','Panoramica','Il tuo spazio personale','⌂'],['programs','I miei percorsi','Le voci che aggiungi','⌕'],['universities','Le mie università','Le voci che aggiungi','⌂'],['favorites','La mia selezione','Percorsi salvati e candidature','♡'],['compare','Confronta','Affianca fino a quattro percorsi','⇄'],['applications','Candidature','Checklist e prossime scadenze','↗']];
function setTheme(theme,persist=false){theme=theme==='dark'?'dark':'light';document.documentElement.dataset.theme=theme;if(persist){try{localStorage.setItem('atlas-appearance',theme)}catch{}}const meta=$('meta[name="theme-color"]');if(meta)meta.content=theme==='dark'?'#0c1422':'#eef3f9';const button=$('#theme-toggle');if(button){button.setAttribute('aria-label',theme==='dark'?'Passa al tema chiaro':'Passa al tema scuro');button.title=theme==='dark'?'Passa al tema chiaro':'Passa al tema scuro'}}
function renderCommandResults(){const output=$('#command-results'),input=$('#command-search');if(!output)return;const q=(input?.value||'').trim().toLocaleLowerCase('it');const pages=commandPages.filter(([,name,meta])=>!q||`${name} ${meta}`.toLocaleLowerCase('it').includes(q));const programs=q&&D?D.programs.filter(p=>[p.name,p.university,p.city,p.region,...(p.partners||[]),...(p.notes||[])].join(' ').toLocaleLowerCase('it').includes(q)).slice(0,6):[];let html='';if(pages.length)html+=`<div class="command-section-label">Sezioni</div>${pages.map(([view,name,meta,icon])=>`<button type="button" class="command-option" data-command-view="${view}"><span class="command-option-icon" aria-hidden="true">${icon}</span><span class="command-option-text"><span class="command-option-title">${name}</span><span class="command-option-meta">${meta}</span></span><kbd>↵</kbd></button>`).join('')}`;if(programs.length)html+=`<div class="command-section-label">Percorsi</div>${programs.map(p=>`<button type="button" class="command-option" data-command-program="${esc(p.id)}"><span class="command-option-icon" aria-hidden="true">↗</span><span class="command-option-text"><span class="command-option-title">${esc(p.name)}</span><span class="command-option-meta">${esc(p.university)} · ${esc(p.city)}</span></span><kbd>#${p.rank}</kbd></button>`).join('')}`;output.innerHTML=html||`<div class="command-empty">${q?'Nessun risultato. Prova con un altro nome o una città.':'Digita per cercare percorsi o università.'}</div>`}
function openCommandPalette(){const dialog=$('#command-palette');if(!dialog)return;if(!dialog.open)dialog.showModal();const input=$('#command-search');if(input){input.value='';renderCommandResults();requestAnimationFrame(()=>input.focus())}}
const legend={M:'Master autonomo o contenitore. La ricerca dipende anche dal laboratorio.',T:'Track, major o concentrazione interna: non un titolo autonomo.',M1:'Primo anno francese; normalmente è il punto di ingresso dopo L-2.',M2:'Secondo anno francese; accesso diretto dopo L-2 non automatico.',J:'Titolo congiunto.',D:'Doppio o multiplo titolo.',C:'Collaborazione didattica: doppio titolo non verificato.','·M':'Mobilità strutturata.',DE:'Tedesco richiesto.',L:'Lingua da verificare; intero percorso in inglese non confermato.',E:'Piano in inglese da costruire e confermare nei moduli.',A:'Accesso particolare o equivalenza L-2 da verificare.','?':'Offerta, struttura o ingresso 2027 da riconfermare.',CN:'Ateneo europeo, programma in Cina.'};
let D,state={favorites:[],compare:[],records:{}},basePrograms=[],baseUniversities=[],aiPending=null,catalogManagerKind='programs',view='overview',homeTab='3',region='Tutte',query='',uni='',kind='',condition='',sort='name',favoritesOnly=false,layout='cards',toastTimer;
const save=()=>store ? store.save(state) : false;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
let draftDirty=false, draftTimer;
function scheduleDraft(){draftDirty=true;clearTimeout(draftTimer);draftTimer=setTimeout(flushDraft,350)}
function flushDraft(){
  if(!draftDirty)return;
  clearTimeout(draftTimer);
  const f=$('#record-form');if(!f)return;
  const v=new FormData(f);
  state.records[f.dataset.id]={stage:v.get('stage'),deadline:v.get('deadline'),deadlineUrl:v.get('deadlineUrl'),notes:v.get('notes'),checklist:[0,1,2,3,4].filter(i=>v.has('check'+i)),updatedAt:Date.now()};
  draftDirty=false;save();
}
function previewImport(data){
  if(!['marea','master-atlas-2027'].includes(data.app)||![1,2].includes(data.version)||!Array.isArray(data.state?.favorites)||!data.state?.records||typeof data.state.records!=='object')throw Error('Backup non valido');
  flushDraft();pendingImport=AtlasCore.normalize(data.state,{programs:basePrograms,universities:baseUniversities,legacyIds:D.legacyIds,retiredProgramIds:D.retiredProgramIds});
  const conflicts=AtlasCore.conflicts(state,pendingImport);
  $('#backup-content').innerHTML=`<div class="eyebrow">IMPORTAZIONE PROTETTA</div><h2 class="page-title" style="font-size:34px">Controlla il backup.</h2><p>${Object.keys(pendingImport.records).length} schede · ${pendingImport.favorites.length} preferiti · <b>${conflicts.length} conflitti</b></p><p>Le note esistenti vengono mantenute per impostazione predefinita. Verrà creata una copia di recupero prima di applicare il backup.</p>${conflicts.length?`<details><summary>Confronta le schede in conflitto</summary>${conflicts.map(id=>`<div class="notice"><b>${esc(find(id).name)}</b><p>Attuale: ${esc(state.records[id].notes||'Nessuna nota')} · ${esc(state.records[id].stage||'Non monitorata')}</p><p>Nel backup: ${esc(pendingImport.records[id].notes||'Nessuna nota')} · ${esc(pendingImport.records[id].stage||'Non monitorata')}</p></div>`).join('')}</details><label class="check-label"><input id="replace-import" type="checkbox">Sostituisci anche le schede esistenti con quelle del backup</label>`:''}<div class="dialog-actions"><button class="button" data-cancel-import>Annulla</button><button class="button primary" data-apply-import>Applica importazione</button></div>`;
  $('#backup-dialog').showModal();
}
async function showRecovery(){
  const local=store.snapshots();
  $('#backup-content').innerHTML=`<h2 class="page-title" style="font-size:34px">Copie di recupero.</h2><p>Scarica una copia, poi importala per confrontare le differenze prima di ripristinare.</p><h3>Su questo browser</h3>${local.length?local.map((s,i)=>`<p><button class="button" data-local-recovery="${i}">↓ ${esc(new Date(s.at).toLocaleString(AtlasI18n.localeTag))} · ${esc(s.reason)}</button></p>`).join(''):'<p>Nessuna copia locale precedente.</p>'}<div id="cloud-backups">Caricamento copie cloud…</div><div class="dialog-actions"><button class="button" data-cancel-import>Chiudi</button></div>`;
  $('#backup-dialog').showModal();
  if(!CLOUD_SYNC){$('#cloud-backups').textContent='Le copie di recupero restano su questo browser. Esporta un backup per conservarle anche altrove.';return;}
  try{const r=await fetch('/api/backups',{cache:'no-store'});if(!r.ok)throw Error();const data=await r.json();$('#cloud-backups').innerHTML='<h3>Nel tuo spazio privato</h3>'+ (data.backups.length?data.backups.map(b=>`<p><button class="button" data-cloud-recovery="${Number(b.revision)}">↓ Versione ${Number(b.revision)} · ${esc(new Date(b.created_at).toLocaleString(AtlasI18n.localeTag))}</button></p>`).join(''):'<p>Nessuna copia cloud precedente.</p>');}
  catch{if($('#cloud-backups'))$('#cloud-backups').textContent='Copie cloud non disponibili: verifica accesso o connessione.'}
}
document.addEventListener('click',async e=>{
  const b=e.target.closest('button');if(!b)return;
  if(b.hasAttribute('data-cancel-import')){$('#backup-dialog').close();pendingImport=null;}
  if(b.hasAttribute('data-apply-import')&&pendingImport){
    store.snapshot(state,'Prima dell’importazione');
    state=AtlasCore.importBackup(state,pendingImport,!!$('#replace-import')?.checked,Date.now());
    save();pendingImport=null;$('#backup-dialog').close();render();toast('Backup importato · copia di recupero disponibile');
  }
  if(b.dataset.localRecovery!==undefined){const copy=store.snapshots()[Number(b.dataset.localRecovery)];if(copy)download('marea-recupero.json',JSON.stringify({app:'marea',version:2,state:JSON.parse(copy.body)},null,2),'application/json');}
  if(b.dataset.cloudRecovery!==undefined){try{const r=await fetch('/api/backups/'+Number(b.dataset.cloudRecovery),{cache:'no-store'});if(!r.ok)throw Error();download('marea-recupero-cloud.json',JSON.stringify(await r.json(),null,2),'application/json');}catch{toast('Copia cloud non disponibile')}}
});
const find=id=>D.programs.find(p=>p.id===id)||basePrograms.find(p=>p.id===id),findCatalogOrPersonal=id=>D.programs.find(p=>p.id===id)||basePrograms.find(p=>p.id===id)||AtlasCore.normalizeCustomPrograms(state.customPrograms).find(p=>p.id===id&&!p.deletedAt),rec=id=>state.records[id]||{};
function syncPersonalCatalog(source=state){if(!D)return;const selectedPrograms=new Set(Object.entries(source.catalogPrograms||{}).filter(([,item])=>item.included).map(([id])=>id));const selectedUniversities=new Set(Object.entries(source.catalogUniversities||{}).filter(([,item])=>item.included).map(([id])=>id));const custom=AtlasCore.normalizeCustomPrograms(source.customPrograms).filter(p=>!p.deletedAt).map(p=>({...p,notes:p.notes?[p.notes]:[],partners:[],type:'Percorso personale',conditions:'—',custom:true}));const customUniversities=AtlasCore.normalizeCustomUniversities(source.customUniversities).filter(item=>!item.deletedAt).map(item=>({...item,rank:999999,offer:item.offer||'Ateneo aggiunto al tuo atlante.',custom:true}));D={...D,programs:[...basePrograms.filter(p=>selectedPrograms.has(p.id)),...custom],universities:[...baseUniversities.filter(u=>selectedUniversities.has(u.id)),...customUniversities]}}
function showAIPersonalizer(){const dialog=$('#ai-dialog');if(!dialog)return;aiPending=null;$('#ai-request').value='';$('#ai-prompt').value='';$('#ai-response').value='';$('#ai-preview').hidden=true;$('#ai-apply').hidden=true;$('#ai-message').textContent='';$('#mcp-url').value=`${location.origin}/api/atlas-mcp`;dialog.showModal();loadMcpConnections()}
function aiPrompt(){const prompt=AtlasAI.createPrompt({programs:basePrograms,universities:baseUniversities},state,globalThis.AtlasI18n?.locale||'it').replace('[SCRIVI QUI COSA VUOI CAMBIARE]',$('#ai-request').value.trim()||'[DESCRIVI OBIETTIVI, INTERESSI E PREFERENZE]');$('#ai-prompt').value=prompt;return prompt}
async function loadMcpConnections(){const list=$('#mcp-connections');if(!list||!CLOUD_SYNC){if(list)list.textContent='Il collegamento diretto richiede un profilo con sincronizzazione cloud.';return}list.textContent='Controllo collegamenti…';try{const response=await fetch('/api/auth/mcp/clients',{cache:'no-store'});if(!response.ok)throw Error();const data=await response.json(),connections=(data.clients||[]).map(client=>`<div class="mcp-connection"><span><strong>${esc(client.name)}</strong><small>Collegato il ${esc(new Date(client.connectedAt).toLocaleDateString(AtlasI18n.localeTag))}</small></span><button class="button" type="button" data-mcp-revoke="${esc(client.id)}" data-mcp-name="${esc(client.name)}">${AtlasI18n.translate('Revoca')}</button></div>`);if(data.siteMcpLinked)connections.push(`<div class="mcp-connection"><span><strong>${AtlasI18n.translate('ChatGPT · app Marea')}</strong><small>${AtlasI18n.translate('Collegamento app ChatGPT (Sites)')}</small></span><button class="button" type="button" data-mcp-site-revoke aria-label="${AtlasI18n.translate('Revoca collegamento ChatGPT')}">${AtlasI18n.translate('Revoca')}</button></div>`);list.innerHTML=connections.join('')||`<p>${AtlasI18n.translate('Nessuna IA collegata a questo profilo.')}</p>`}catch{list.textContent='Non riesco a leggere i collegamenti. Riprova tra poco.'}}
async function generateSiteMcpLinkCode(button){const output=$('#mcp-site-link-result'),copy=$('#mcp-site-link-copy'),message=$('#ai-message');if(!output||!copy)return;button.disabled=true;copy.hidden=true;output.replaceChildren();message.textContent=AtlasI18n.translate('Genero un codice di collegamento…');try{const response=await fetch('/api/auth/mcp/site-link-code',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:'{}'}),data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.error||'Non riesco a generare il codice. Accedi al profilo e riprova.');copy.dataset.code=data.code;const code=document.createElement('code');code.textContent=data.code;output.replaceChildren(code,document.createTextNode(` · ${AtlasI18n.translate('Scade tra 10 minuti')}`));copy.hidden=false;try{await navigator.clipboard.writeText(data.code);message.textContent=AtlasI18n.translate('Codice copiato negli appunti.')}catch{message.textContent=AtlasI18n.translate('Il codice è visibile qui sopra; copialo e incollalo in ChatGPT.')}}catch(error){message.textContent=error.message||'Non riesco a generare il codice. Riprova.'}finally{button.disabled=false}}
function previewAIResponse(){try{const planned=AtlasAI.parseResponse($('#ai-response').value,{programs:basePrograms,universities:baseUniversities},state),items=planned.selectedProgramIds.map(find).filter(Boolean),customNames=planned.customProgramsToAdd.map(p=>`${p.name} · ${p.university}`),applicationNames=planned.applicationUpdates.map(item=>findCatalogOrPersonal(item.programId)?.name||item.programId);aiPending=planned;const rows=[`Preferenze: ${planned.preferences===undefined?'mantieni quelle attuali':'aggiorna'}`,`Shortlist: ${items.length} percorsi selezionati`,...items.slice(0,8).map(p=>`• ${p.name} — ${p.university}`),...(items.length>8?[`• e altri ${items.length-8}`]:[]),`Percorsi da confrontare: ${planned.compareProgramIds?.length??state.compare.length}`,`Nuovi percorsi personali: ${customNames.length}`,...customNames.map(name=>`• ${name}`),`Candidature da aggiornare: ${applicationNames.length}`,...applicationNames.slice(0,8).map(name=>`• ${name}`)];$('#ai-preview').textContent=rows.join('\n');$('#ai-preview').hidden=false;$('#ai-apply').hidden=false;$('#ai-message').textContent='Controlla il riepilogo. L’IA non può salvare le modifiche finché non premi “Applica al mio atlante”.'}catch(error){aiPending=null;$('#ai-preview').hidden=true;$('#ai-apply').hidden=true;$('#ai-message').textContent=error.message||'Risposta non valida.'}}
function applyAIResponse(){if(!aiPending)return;store.snapshot(state,'Prima della personalizzazione IA');const now=Date.now(),added=[];if(aiPending.preferences!==undefined){state.preferences=aiPending.preferences.trim();state.preferencesUpdatedAt=now}for(const id of state.favorites)state.favoritesUpdated[id]={selected:false,updatedAt:now};for(const id of aiPending.selectedProgramIds)state.favoritesUpdated[id]={selected:true,updatedAt:now};state.favorites=[...aiPending.selectedProgramIds];state.catalogPrograms||={};for(const id of [...aiPending.selectedProgramIds,...(aiPending.compareProgramIds||[])]){const program=basePrograms.find(p=>p.id===id);if(program&&!state.catalogPrograms[id]?.included){state.catalogPrograms[id]={included:true,updatedAt:now};includePersonalUniversitiesForProgram(program,now)}}if(aiPending.compareProgramIds!==undefined){state.compare=[...aiPending.compareProgramIds];state.compareUpdated=now}for(const item of aiPending.customProgramsToAdd){const id=`custom-${crypto.randomUUID()}`;const program={...item,id,createdAt:now,updatedAt:now,deletedAt:0};state.customPrograms.push(program);ensurePersonalUniversity(program.university,program,now);state.favoritesUpdated[id]={selected:true,updatedAt:now};state.favorites.push(id);added.push(id)}for(const update of aiPending.applicationUpdates){const old=rec(update.programId);state.records[update.programId]={...old,...update,updatedAt:now}}state=AtlasCore.normalize(state,{programs:basePrograms,universities:baseUniversities,legacyIds:D.legacyIds,retiredProgramIds:D.retiredProgramIds});syncPersonalCatalog(state);const ok=save();aiPending=null;$('#ai-dialog').close();render();toast(ok?`Atlante aggiornato · ${added.length} nuovi percorsi personali`:'Modifica applicata, ma il salvataggio locale non è riuscito')}
async function copyAIText(textarea){if(!textarea.value)aiPrompt();try{await navigator.clipboard.writeText(textarea.value);$('#ai-message').textContent='Prompt copiato. Incollalo nella tua IA e poi riporta qui la risposta JSON.'}catch{textarea.focus();textarea.select();$('#ai-message').textContent='Seleziona e copia il prompt, poi incollalo nella tua IA preferita.'}}
function badge(p){return '<span class="badge">'+esc(p.type)+'</span>'}
function heart(p){return `<button class="icon-button ${state.favorites.includes(p.id)?'selected':''}" data-fav="${p.id}" aria-label="${state.favorites.includes(p.id)?'Rimuovi dai':'Aggiungi ai'} preferiti: ${esc(p.name)}" aria-pressed="${state.favorites.includes(p.id)}">${state.favorites.includes(p.id)?'♥':'♡'}</button>`}
function checkbox(p){return `<label class="compare-check"><input type="checkbox" data-compare="${p.id}" ${state.compare.includes(p.id)?'checked':''}> Confronta</label>`}
function title(eyebrow,name,sub,action=''){return `<div class="title-row"><div><div class="eyebrow">${eyebrow}</div><h1 class="page-title">${name}</h1><p class="subtitle">${sub}</p></div>${action}</div>`}
function updateChrome(){for(const a of $$('#nav a')){a.classList.toggle('active',a.dataset.view===view);if(a.dataset.view===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')}const pageLabel=$('#page-label');if(pageLabel)pageLabel.textContent=labels[view];$('#fav-count').textContent=state.favorites.filter(id=>find(id)).length;$('#compare-count').textContent=state.compare.length;const t=$('#compare-tray');t.hidden=!state.compare.length||view==='compare';t.innerHTML=`<span>${state.compare.length} percorsi da confrontare</span><a class="button" href="#compare">Confronta ⇄</a><button class="text-button" data-clear-compare aria-label="Svuota confronto">×</button>`}
function overview(){$('#main').innerHTML=title('IL TUO SPAZIO','Il tuo atlante.','Aggiungi percorsi e università al tuo spazio personale.',`<button class="button primary" data-open-custom-catalog="programs">＋ Crea un percorso</button> <button class="button" data-open-custom-catalog="universities">＋ Crea un’università</button>`)+`<div class="empty"><h2>Il tuo atlante parte da te.</h2><p>Crea le voci che vuoi seguire e organizza preferiti, confronti e candidature.</p><div class="dialog-actions"><a class="button" href="#programs">I miei percorsi</a><a class="button" href="#universities">Le mie università</a></div></div>`}
function render(){updateChrome();({overview,programs:catalog,favorites:catalog,universities,compare:comparison,applications}[view]||overview)()}
function card(p){const inCatalog=!!p.custom||!!state.catalogPrograms?.[p.id]?.included;return `<article class="program-card"><div class="card-top"><span class="rank-badge"><strong>${p.custom?'PERSONALE':inCatalog?`#${p.rank}`:`PRECEDENTE · #${p.rank}`} </strong> · ${p.region}</span><div class="card-actions">${heart(p)}${inCatalog?`<button class="text-button remove-personal" type="button" data-remove-personal-program="${esc(p.id)}" aria-label="Rimuovi ${esc(p.name)} dal tuo catalogo" title="Rimuovi dal tuo catalogo">Rimuovi</button>`:`<button class="button" type="button" data-toggle-catalog-program="${esc(p.id)}">Aggiungi al mio catalogo</button>`}</div></div><button class="card-title" data-detail="${esc(p.id)}">${esc(p.name)}</button><p class="card-university">${esc(p.university)}</p><p class="card-city">⌖ ${esc(p.city)}</p><div class="badges">${badge(p)}${rec(p.id).stage?`<span class="badge">${esc(rec(p.id).stage)}</span>`:''}</div><div class="card-bottom">${checkbox(p)}<button class="detail-link" data-detail="${esc(p.id)}">Apri scheda ↗</button></div></article>`}
function catalogManagerButtons(kind){return `<div class="catalog-manager-actions"><button class="button primary" type="button" data-open-custom-catalog="${kind}">＋ Crea voce personale</button></div>`}
function updateCatalogManagerFields(){const programs=catalogManagerKind==='programs';$('#custom-program-fields').hidden=!programs;$('#custom-university-fields').hidden=programs;for(const el of $$('#custom-program-fields input, #custom-program-fields select, #custom-program-fields textarea'))el.disabled=!programs;for(const el of $$('#custom-university-fields input, #custom-university-fields select, #custom-university-fields textarea'))el.disabled=programs}
function ensurePersonalUniversity(name,details={},now=Date.now()){const key=AtlasCore.normalizeUniversityKey(name),shared=baseUniversities.find(item=>AtlasCore.normalizeUniversityKey(item.name)===key);if(shared){state.catalogUniversities||={};state.catalogUniversities[shared.id]={included:true,updatedAt:now};return}state.customUniversities||=[];let item=state.customUniversities.find(value=>AtlasCore.normalizeUniversityKey(value.name)===key);if(item)Object.assign(item,{city:details.city||item.city||'',country:details.country||item.country||'',region:details.region||item.region||'Europa',url:details.url||item.url||'',offer:details.offer||item.offer||'',updatedAt:now,deletedAt:0});else state.customUniversities.push({id:`custom-uni-${crypto.randomUUID()}`,name:String(name).trim(),city:details.city||'',country:details.country||'',region:details.region||'Europa',url:details.url||'',offer:details.offer||'',createdAt:now,updatedAt:now,deletedAt:0})}
function includePersonalUniversitiesForProgram(program,now=Date.now()){const matches=baseUniversities.filter(university=>AtlasCore.belongsTo(program,university.name));if(matches.length){state.catalogUniversities||={};for(const university of matches)state.catalogUniversities[university.id]={included:true,updatedAt:now}}else ensurePersonalUniversity(program.university,program,now)}
function showCatalogManager(kind='programs',focusForm=true){catalogManagerKind=kind==='universities'?'universities':'programs';const dialog=$('#personal-catalog-dialog');if(!dialog)return;$('#catalog-manager-title').textContent=catalogManagerKind==='programs'?'Crea un percorso personale':'Crea un’università personale';updateCatalogManagerFields();if(!dialog.open)dialog.showModal();$('.custom-entry-details').open=true;(catalogManagerKind==='programs'?$('#custom-program-name'):$('#custom-university-name'))?.focus()}
function catalog(){const favorite=view==='favorites';const explorePrograms=favorite?[...new Map([...D.programs,...basePrograms.filter(p=>state.favorites.includes(p.id))].map(p=>[p.id,p])).values()]:D.programs;const controls=favorite?'':catalogManagerButtons('programs');$('#main').innerHTML=title(favorite?'LE POSSIBILITÀ CHE CONTANO':'TROVA LA TUA DIREZIONE',favorite?'La mia selezione.':'Un mondo di possibilità.',favorite?'I tuoi percorsi preferiti, con note e candidature sempre a portata di mano.':`${explorePrograms.length} percorsi nel tuo catalogo personale: crea percorsi tuoi.`,favorite?'':`${controls}<button class="button" data-export-csv>↓ Esporta risultati CSV</button>`)+`<div class="ranking-tabs">${['Europa','Extra-Europa','Tutte'].map(r=>`<button class="tab ${region===r?'active':''}" data-region-tab="${r}">${r}${r==='Tutte'?` · ${explorePrograms.length}`:r==='Europa'?` · ${explorePrograms.filter(p=>p.region==='Europa').length}`:` · ${explorePrograms.filter(p=>p.region==='Extra-Europa').length}`}</button>`).join('')}</div><div class="toolbar"><div class="search"><input id="search" type="search" placeholder="Cerca un percorso, una città, un’università…" aria-label="Cerca percorsi" value="${esc(query)}"></div><select id="university-filter" aria-label="Filtra università"><option value="">Tutte le università</option>${[...new Set([...explorePrograms.map(p=>p.university),...explorePrograms.flatMap(p=>p.partners||[])])].sort().map(u=>`<option ${uni===u?'selected':''}>${esc(u)}</option>`).join('')}</select><select id="type-filter" aria-label="Filtra tipo"><option value="">Tutti i tipi</option>${[...new Set(explorePrograms.map(p=>p.type))].sort().map(t=>`<option value="${esc(t)}" ${kind===t?'selected':''}>${esc(t)}</option>`).join('')}</select><select id="condition-filter" aria-label="Filtra condizioni"><option value="">Tutte le condizioni</option>${[['none','Nessuna sigla'],['DE','DE · Tedesco'],['L','L · Lingua da verificare'],['E','E · Piano in inglese'],['A','A · Accesso particolare'],['?','? · 2027 da confermare'],['CN','CN · In Cina']].map(([v,l])=>`<option value="${v}" ${condition===v?'selected':''}>${l}</option>`).join('')}</select><select id="sort" aria-label="Ordina risultati">${[['name','Nome A–Z'],['university','Università A–Z']].map(([v,l])=>`<option value="${v}" ${sort===v?'selected':''}>${l}</option>`).join('')}</select><button class="button" data-reset-filters>Ripristina filtri</button></div><div class="result-bar"><span id="result-count"></span><div class="view-switch"><button class="chip ${layout==='cards'?'active':''}" data-layout="cards" aria-label="Vista schede">▦ Schede</button><button class="chip ${layout==='table'?'active':''}" data-layout="table" aria-label="Vista tabella">☷ Tabella</button></div><label class="check-label"><input id="favorites-only" type="checkbox" ${favoritesOnly?'checked':''}> Solo preferiti</label></div><div id="results"></div>`;renderResults()}

function renderResults(){const a=filtered();$('#result-count').textContent=`${a.length} percorsi · ${region==='Tutte'?'Le posizioni sono separate per area geografica':region}`;$('#results').innerHTML=a.length?(layout==='cards'?`<div class="cards">${a.map(card).join('')}</div>`:`<div class="table-wrap"><table class="data-table"><thead><tr><th>POSIZIONE</th><th>PERCORSO</th><th>UNIVERSITÀ / CITTÀ</th><th>TIPO / CONDIZIONI</th><th>SELEZIONA</th></tr></thead><tbody>${a.map(p=>`<tr><td>#${p.rank}<br>${p.region}</td><td><button class="table-title" data-detail="${p.id}">${esc(p.name)}</button></td><td>${esc(p.university)}<br><small>${esc(p.city)}</small></td><td>${badge(p)}</td><td>${heart(p)} ${checkbox(p)}</td></tr>`).join('')}</tbody></table></div>`):`<div class="empty"><h2>${view==='favorites'?'La tua shortlist inizia da una curiosità.':D.programs.length===0?'Il tuo catalogo di percorsi è vuoto.':'Nessun percorso trovato.'}</h2><p>${view==='favorites'?'Salva i percorsi con il cuore per ritrovarli qui.':D.programs.length===0?'Crea percorsi personali oppure aggiungili con la tua IA.':'Prova a cambiare ricerca o a ripristinare i filtri.'}</p>${D.programs.length===0&&view!=='favorites'?'<button type="button" class="button primary" data-open-ai>Personalizza con la tua IA ↗</button>':'<a class="button" href="#programs">Esplora i percorsi ↗</a>'}</div>`}
function uniquePersonalUniversities(){return D.universities.filter(university=>university.custom)}
function universities(){const personal=uniquePersonalUniversities().filter(u=>region==='Tutte'||u.region===region);const cards=personal.map(u=>'<article class="uni-card personal-university"><h2>'+esc(u.name)+'</h2><small class="card-city">⌖ '+esc([u.city,u.country].filter(Boolean).join(', ')||'Sede da verificare')+'</small><p>'+esc(u.offer||'Università aggiunta al tuo spazio personale.')+'</p><button class="text-button remove-personal" type="button" data-remove-personal-university="'+esc(u.id)+'">Rimuovi</button></article>').join('');$('#main').innerHTML=title('IL TUO SPAZIO','Le mie università.','Università che hai aggiunto al tuo atlante.',catalogManagerButtons('universities'))+'<div class="university-grid">'+(cards||'<div class="empty"><h2>Non hai ancora aggiunto università.</h2><p>Crea una voce personale per iniziare.</p><button type="button" class="button primary" data-open-custom-catalog="universities">＋ Crea università</button></div>')+'</div>'}
function comparison(){const a=state.compare.map(find).filter(Boolean);$('#main').innerHTML=title('AFFIANCA LE TUE POSSIBILITÀ','Una scelta più chiara.','Confronta fino a quattro percorsi. ',`<button class="button" data-clear-compare>Svuota confronto</button>`)+(a.length?`<div class="compare-wrap"><table class="compare-table"><thead><tr><th>Percorsi</th>${a.map(p=>`<th>${esc(p.name)}<br><button class="detail-link" data-remove-compare="${p.id}">Rimuovi ×</button></th>`).join('')}</tr></thead><tbody>${[['Posizione',p=>`#${p.rank} · ${p.region}`],['Università',p=>esc(p.university)],['Sede',p=>esc(p.city)],['Tipo',p=>`${esc(p.type)}<br><small>${esc(typeExplanation(p.type))}</small>`],['Condizioni',p=>conditionsText(p)],['Dettagli',p=>esc(p.notes.join(' ')||'Nessuna nota associata. Aggiungi i dettagli che vuoi ricordare.')],['Candidatura',p=>esc(rec(p.id).stage||'Non monitorata')],['Scadenza personale',p=>esc(rec(p.id).deadline||'Non inserita')],['Le tue note',p=>esc(rec(p.id).notes||'—')],['Azioni',p=>`<button class="button" data-detail="${p.id}">Apri scheda ↗</button>`]].map(([label,fn])=>`<tr><td>${label}</td>${a.map(p=>`<td>${fn(p)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="notice">Confronta i dettagli che hai inserito per ciascuna voce.</div>`:`<div class="empty"><h2>Metti le alternative una accanto all’altra.</h2><p>Seleziona “Confronta” sulle schede dei percorsi per iniziare.</p><a class="button primary" href="#programs">Scegli i percorsi ↗</a></div>`)}
function deadlineStatus(date){if(!date)return '';const today=new Date();const local=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;return date<local?'overdue':''}
function applications(){const a=[...new Map([...basePrograms,...D.programs].map(p=>[p.id,p])).values()].filter(p=>rec(p.id).stage);$('#main').innerHTML=title('DALLE IDEE AI PROSSIMI PASSI','Le tue candidature.','Organizza il percorso, aggiungi scadenze e tieni traccia dei documenti.',`<a class="button primary" href="#programs">+ Scegli un percorso</a>`)+`<div class="notice">Le scadenze si inseriscono nelle schede dopo la verifica sul sito ufficiale. Spostare una scheda in “Inviata” registra il tuo stato: non invia una candidatura.</div><div class="board">${stages.map(s=>`<section class="column"><h2>${s}<b>${a.filter(p=>rec(p.id).stage===s).length}</b></h2>${a.filter(p=>rec(p.id).stage===s).sort((a,b)=>(rec(a.id).deadline||'9999').localeCompare(rec(b.id).deadline||'9999')).map(p=>`<article class="application"><span class="eyebrow" style="font-size:8px">${esc(p.university)}</span><h3><button class="table-title" data-detail="${p.id}">${esc(p.name)}</button></h3><p>${esc(p.city)}</p>${rec(p.id).deadline?`<span class="deadline ${deadlineStatus(rec(p.id).deadline)}">◷ ${esc(rec(p.id).deadline)} ${deadlineStatus(rec(p.id).deadline)?'· trascorsa':''}</span>`:'<span class="deadline">Nessuna scadenza inserita</span>'}<select data-stage="${p.id}" aria-label="Stato candidatura ${esc(p.name)}">${stages.map(t=>`<option value="${esc(t)}" ${s===t?'selected':''}>${t}</option>`).join('')}</select></article>`).join('')}${!a.some(p=>rec(p.id).stage===s)?'<p class="subtitle" style="font-size:11px">I tuoi prossimi passi appariranno qui.</p>':''}</section>`).join('')}</div>`}
function typeExplanation(type){if(type.startsWith('M1–M2'))return 'Percorso francese M1–M2; ·M indica mobilità.';return type.split('·').map(t=>legend[t]||t).join(' ')}
function conditionsText(p){if(p.conditions==='—')return 'Aggiungi qui i dettagli da verificare.';return p.conditions.split(/[·, /]+/).filter(Boolean).map(s=>`${esc(s)}: ${esc(legend[s]||'Consulta i dettagli inseriti.')}`).join('<br>')}
function openDetail(id){const p=find(id);if(!p)return;const r=rec(id);$('#detail-content').innerHTML=`<div class="dialog-head"><button class="icon-button dialog-close" data-close aria-label="Chiudi scheda">×</button><div class="eyebrow">${p.custom?'PERCORSO PERSONALE':`#${p.rank} · ${p.region} · DOSSIER 2027`}</div><h2>${esc(p.name)}</h2><div class="card-university">${esc(p.university)} · ${esc(p.city)}</div><div class="badges">${badge(p)}</div></div><div class="dialog-body"><div class="dialog-meta"><div><small>TIPO DI PERCORSO</small>${esc(typeExplanation(p.type))}</div><div><small>DETTAGLI</small>${conditionsText(p)}</div></div>${p.notes.length?`<div class="eyebrow">${p.custom?'NOTE PERSONALI':'NOTE'}</div>${p.notes.map(n=>`<p>${esc(n)}</p>`).join('')}`:'<p>Aggiungi i dettagli che vuoi ricordare per questa voce.</p>'}${p.url?`<a class="button" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Sito ufficiale ↗</a>`:`<p class="notice">Percorso aggiunto al tuo atlante. Verifica le informazioni e il sito ufficiale prima di candidarti.</p>`}<form id="record-form" data-id="${id}"><div class="section-heading"><h2>Il tuo piano</h2>${heart(p)}</div><div class="two-fields"><label class="field">Stato della candidatura<select name="stage"><option value="">Non monitorata</option>${stages.map(s=>`<option value="${esc(s)}" ${r.stage===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="field">Scadenza verificata da te<input type="date" name="deadline" value="${esc(r.deadline||'')}" min="2020-01-01" max="2040-12-31"></label></div><label class="field">Link al bando / fonte della scadenza<input type="url" name="deadlineUrl" placeholder="https://…" value="${esc(r.deadlineUrl||'')}"></label><label class="field">Le tue note<textarea name="notes" placeholder="Laboratori interessanti, requisiti da controllare, idee per il progetto…">${esc(r.notes||'')}</textarea></label><div class="eyebrow">LA TUA CHECKLIST</div><div class="checklist">${['CV','Motivazione','Transcript','Inglese','Referenze'].map((s,i)=>`<label><input type="checkbox" name="check${i}" ${r.checklist?.includes(i)?'checked':''}>${s}</label>`).join('')}</div><div class="dialog-actions"><label class="compare-check"><input type="checkbox" data-compare="${id}" ${state.compare.includes(id)?'checked':''}> Confronta questo percorso</label><button type="submit" class="button primary">Salva il mio piano ✓</button></div><p style="font-size:10px">${CLOUD_SYNC?'Salvataggio automatico · copia locale e sincronizzazione privata.':'Salvataggio automatico solo su questo browser. Esporta un backup per conservare o trasferire i progressi.'} Nessuna candidatura viene inviata.</p></form></div>`;$$('button[data-fav]',$('#record-form')).forEach(b=>b.type='button');$('#detail').showModal()}
function download(name,body,type){const url=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function backup(){download('marea-backup.json',JSON.stringify({app:'marea',version:2,exported:new Date().toISOString(),state},null,2),'application/json');toast('Backup esportato')}
function csv(){const lines=[['Area','Posizione','Programma','Università','Città','Tipo','Condizioni','URL','Preferito','Stato candidatura','Scadenza personale','Note personali'],...filtered().map(p=>[p.region,p.rank,p.name,p.university,p.city,p.type,p.conditions,p.url,state.favorites.includes(p.id)?'Sì':'No',rec(p.id).stage||'',rec(p.id).deadline||'',rec(p.id).notes||''])];const safe=v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};download('marea-selezione.csv','\uFEFF'+lines.map(row=>row.map(safe).join(';')).join('\r\n'),'text/csv;charset=utf-8')}
document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-university]');if(!b)return;
 if(b.dataset.openAi!==undefined){showAIPersonalizer();return}
 if(b.hasAttribute('data-open-catalog')){showCatalogManager(b.getAttribute('data-open-catalog'));return}
 if(b.hasAttribute('data-open-custom-catalog')){showCatalogManager(b.getAttribute('data-open-custom-catalog'),true);return}
 if(b.dataset.managerKind){catalogManagerKind=b.dataset.managerKind;updateCatalogManagerFields();return}
 if(b.dataset.toggleCatalogProgram){toggleCatalogProgram(b.dataset.toggleCatalogProgram);return}
 if(b.dataset.toggleCatalogUniversity){toggleCatalogUniversity(b.dataset.toggleCatalogUniversity);return}
 if(b.dataset.removePersonalProgram){requestCatalogRemoval('programs',b.dataset.removePersonalProgram);return}
 if(b.dataset.removePersonalUniversity){removePersonalUniversity(b.dataset.removePersonalUniversity);return}
 if(b.id==='catalog-remove-confirm'){confirmCatalogRemoval();return}
 if(b.id==='catalog-remove-cancel'){pendingCatalogRemoval=null;$('#catalog-remove-dialog').close();return}
 if(b.id==='catalog-manager-close'){$('#personal-catalog-dialog').close();return}
 if(b.id==='ai-personalize'){showAIPersonalizer();return}
 if(b.id==='ai-close'){$('#ai-dialog').close();return}
 if(b.id==='ai-copy-prompt'){aiPrompt();await copyAIText($('#ai-prompt'));return}
 if(b.id==='mcp-site-link-code'){await generateSiteMcpLinkCode(b);return}
 if(b.id==='mcp-site-link-copy'){try{await navigator.clipboard.writeText(b.dataset.code||'');$('#ai-message').textContent=AtlasI18n.translate('Codice copiato negli appunti.')}catch{$('#ai-message').textContent=AtlasI18n.translate('Il codice è visibile qui sopra; copialo e incollalo in ChatGPT.')}return}
 if(b.id==='ai-preview-response'){previewAIResponse();return}
 if(b.id==='ai-apply'){applyAIResponse();return}
 if(b.id==='mcp-copy-url'){try{await navigator.clipboard.writeText(`${location.origin}/api/atlas-mcp`);$('#ai-message').textContent='Indirizzo MCP copiato: aggiungilo come connettore nella tua IA.'}catch{$('#mcp-url').select();$('#ai-message').textContent='Seleziona e copia l’indirizzo MCP.'}return}
 if(b.dataset.mcpSiteRevoke!==undefined){if(!confirm(AtlasI18n.translate('Revocare il collegamento dell’app ChatGPT a questo profilo? ChatGPT perderà l’accesso ai tuoi dati.')))return;try{const response=await fetch('/api/auth/mcp/clients',{method:'DELETE',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify({siteMcp:true})});if(!response.ok)throw Error();await loadMcpConnections();toast(AtlasI18n.translate('Collegamento ChatGPT revocato'))}catch{toast(AtlasI18n.translate('Non è stato possibile revocare il collegamento. Riprova.'))}return}
 if(b.dataset.mcpRevoke){if(!confirm(AtlasI18n.translate(`Revocare l’accesso di ${b.dataset.mcpName||'questa IA'} a questo profilo?`)))return;try{const response=await fetch('/api/auth/mcp/clients',{method:'DELETE',headers:{'content-type':'application/json'},body:JSON.stringify({clientId:b.dataset.mcpRevoke})});if(!response.ok)throw Error();await loadMcpConnections();toast('Collegamento IA revocato')}catch{toast('Non è stato possibile revocare il collegamento. Riprova.')}return}
 if(b.id==='profile-toggle'){const actions=$('#profile-actions'),open=actions?.hidden;if(actions){actions.hidden=!open;b.setAttribute('aria-expanded',String(open));}return}
 if(b.closest('#profile-actions')){closeProfileMenu();}
 if(b.id==='theme-toggle'){setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark',true);return}
 if(b.id==='command-toggle'){openCommandPalette();return}
 if(b.dataset.commandView){$('#command-palette').close();location.hash=b.dataset.commandView;return}
 if(b.dataset.commandProgram){$('#command-palette').close();openDetail(b.dataset.commandProgram);return}
 if(b.dataset.detail){openDetail(b.dataset.detail);return}
 if(b.hasAttribute('data-close')){flushDraft();$('#detail').close();return}
 if(b.dataset.fav){const id=b.dataset.fav;state.favoritesUpdated[id]={selected:!state.favorites.includes(id),updatedAt:Date.now()};state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();b.classList.toggle('selected',state.favorites.includes(id));b.textContent=state.favorites.includes(id)?'♥':'♡';b.setAttribute('aria-pressed',state.favorites.includes(id));b.setAttribute('aria-label',`${state.favorites.includes(id)?'Rimuovi dai':'Aggiungi ai'} preferiti: ${find(id).name}`);if(!$('#detail').open)render();else updateChrome();return}
 if(b.dataset.homeTab){homeTab=b.dataset.homeTab;render();return}
 if(b.dataset.regionTab){region=b.dataset.regionTab;uni='';render();return}
 if(b.dataset.layout){layout=b.dataset.layout;catalog();return}
 if(b.dataset.university){const mappings={'Queensland — UQ':'UQ','Erasmus University / Erasmus MC':'Erasmus MC'};const name=mappings[b.dataset.university]||b.dataset.university;region=b.dataset.region;uni=name;kind='';condition='';query='';if(!D.programs.some(p=>AtlasCore.belongsTo(p,uni))){uni='';query=name}if(view==='programs')catalog();else location.hash='programs';return}
 if(b.hasAttribute('data-reset-filters')){query='';uni='';kind='';condition='';sort='name';catalog();return}
 if(b.hasAttribute('data-clear-compare')){state.compare=[];state.compareUpdated=Date.now();save();render();return}
 if(b.dataset.removeCompare){state.compare=state.compare.filter(id=>id!==b.dataset.removeCompare);state.compareUpdated=Date.now();save();render();return}
 if(b.hasAttribute('data-export-csv')){csv();return}
 if(b.id==='backup'||b.hasAttribute('data-backup')){backup();return}
 if(b.hasAttribute('data-recovery')){showRecovery();return}
 if(b.id==='import-button'||b.hasAttribute('data-import')){$('#import-file').click();return}

});
document.addEventListener('input',e=>{if(e.target.id==='command-search'){renderCommandResults()}else if(e.target.id==='search'){query=e.target.value;renderResults()}else if(e.target.closest('#record-form'))scheduleDraft()});
function closeProfileMenu(){const actions=$('#profile-actions'),toggle=$('#profile-toggle');if(actions&&!actions.hidden){actions.hidden=true;toggle?.setAttribute('aria-expanded','false')}}
document.addEventListener('click',e=>{if(!e.target.closest('#profile-menu'))closeProfileMenu()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeProfileMenu();const typing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openCommandPalette();return}if(e.key==='/'&&!e.metaKey&&!e.ctrlKey&&!e.altKey&&!typing){e.preventDefault();openCommandPalette();return}const dialog=$('#command-palette');if(!dialog?.open)return;if(e.key==='Enter'&&document.activeElement===$('#command-search')){e.preventDefault();$('.command-option',dialog)?.click();return}if(!['ArrowDown','ArrowUp'].includes(e.key))return;const options=$$('.command-option',dialog);if(!options.length)return;e.preventDefault();const current=options.indexOf(document.activeElement),delta=e.key==='ArrowDown'?1:-1;options[current<0?(delta>0?0:options.length-1):(current+delta+options.length)%options.length].focus()});
document.addEventListener('change',e=>{const t=e.target;if(t.closest('#record-form')&&!t.dataset.compare)scheduleDraft();if(t.dataset.compare){const id=t.dataset.compare;if(t.checked&&state.compare.length>=4){t.checked=false;toast('Puoi confrontare fino a quattro percorsi. Rimuovine uno per continuare.');return}state.compare=t.checked?[...new Set([...state.compare,id])]:state.compare.filter(x=>x!==id);state.compareUpdated=Date.now();save();updateChrome();return}
 if(t.dataset.stage){state.records[t.dataset.stage]={...rec(t.dataset.stage),stage:t.value,updatedAt:Date.now()};save();applications();return}
 if(['university-filter','type-filter','condition-filter','sort'].includes(t.id)){if(t.id==='university-filter')uni=t.value;if(t.id==='type-filter')kind=t.value;if(t.id==='condition-filter')condition=t.value;if(t.id==='sort')sort=t.value;renderResults()}
});
document.addEventListener('submit',e=>{if(e.target.id==='custom-catalog-form'){e.preventDefault();saveCustomCatalogEntry(e.target);return}if(e.target.id!=='record-form')return;e.preventDefault();draftDirty=false;clearTimeout(draftTimer);const f=e.target;const values=new FormData(f);state.records[f.dataset.id]={stage:values.get('stage'),deadline:values.get('deadline'),deadlineUrl:values.get('deadlineUrl'),notes:values.get('notes'),updatedAt:Date.now(),checklist:[0,1,2,3,4].filter(i=>values.has('check'+i))};const ok=save();$('#detail').close();render();if(ok)toast('Il tuo piano è stato salvato ✓')});
$('#import-file').addEventListener('change',async e=>{
  try{const f=e.target.files[0];if(!f)return;if(f.size>5000000)throw Error();previewImport(JSON.parse(await f.text()));}
  catch{toast('Backup non valido. Seleziona un JSON esportato da Marea.');}
  finally{e.target.value='';}
});
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
$('#detail').addEventListener('close',()=>{flushDraft();if(D)render()});
$('#detail').addEventListener('cancel',flushDraft);
$('#command-palette').addEventListener('click',e=>{if(e.target===$('#command-palette')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
$('#ai-dialog').addEventListener('click',e=>{if(e.target===$('#ai-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
$('#ai-dialog').addEventListener('close',()=>{aiPending=null});
window.addEventListener('pagehide',flushDraft);
document.addEventListener('visibilitychange',()=>{if(document.hidden)flushDraft()});
function route(){
  const target=location.hash.slice(1)||'overview';
  flushDraft();
  if($('#detail').open)$('#detail').close();
  if(target!==view){query='';uni='';kind='';condition='';sort='name';region='Tutte';}
  view=Object.hasOwn(labels,target)?target:'overview';const paint=()=>render();const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;if(document.startViewTransition&&!reduced)document.startViewTransition(paint);else paint();window.scrollTo(0,0);
}
window.addEventListener('hashchange',route);
const appReady=globalThis.ATLAS_CONFIG?.accounts===true?globalThis.AtlasAuth.ready:Promise.resolve(null);
appReady.then(user=>{
  if(globalThis.ATLAS_CONFIG?.accounts===true&&!user)return;
  return fetch('data.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(async d=>{
    D=d;basePrograms=D.programs.slice();baseUniversities=D.universities.slice();
    store=new AtlasStore(D,next=>{const changed=JSON.stringify(state)!==JSON.stringify(next);state=next;syncPersonalCatalog(next);if(changed&&!$('#detail').open)render();else updateChrome();},updateSync);
    state=store.state;syncPersonalCatalog(state);route();await store.start();
  });
}).catch(()=>{$('#main').innerHTML='<div class="empty"><h2>Non riesco a caricare il tuo atlante.</h2><p>Ricarica la pagina per riprovare.</p><button class="button" onclick="location.reload()">Ricarica</button></div>'});
if(document.documentElement?.dataset)setTheme(document.documentElement.dataset.theme||'light');
